                              String declarationKey, List<String> tests) throws Exception {
        createBatch(batchKey, material, batchNo, tests, 201);
        bind("op", "CK-RB-" + unique(), List.of(List.of(batchKey, declarationKey, 1)), 201);
        passAll(batchKey, tests);
